/**
 * Tabelas de preço dos fornecedores — transcritas das planilhas recebidas em
 * 16/10 e 23/10/2026 (SOLIS julho/2026, SYLLENT agosto/2026, INOVA agosto/2026,
 * THOLZ março/2026 e a aba SODRAMAR 2015/2016 que veio junto, marcada como
 * desatualizada). Lidas por `POST /products/seed-tabelas-fornecedores`.
 *
 * Regras aplicadas na transcrição:
 * - `precoParcelado` é o preço principal da tabela (até 10x, 3x ou "à vista/30/60");
 *   `precoAVista` é a coluna "A VISTA" quando existe, ou o preço com 5% de
 *   desconto quando a tabela diz "à vista 5% de desconto" (Syllent, Inova GP).
 * - Coletor de piscina Solis é vendido por m² (R$ 188 parc. / R$ 180 à vista);
 *   cada tamanho sai com o preço já multiplicado pela área.
 * - Itens com preço único (união inox, kit polipropileno, areia, vidro
 *   filtrante) têm os dois preços iguais.
 * - Os SKUs são estáveis: rodar o seed de novo atualiza preços e não duplica.
 *
 * Gerado por script a partir das planilhas; não editar à mão — ao receber uma
 * tabela nova, regenerar o arquivo inteiro.
 */
export interface ProdutoTabelaFornecedor {
  sku: string;
  nome: string;
  descricao: string | null;
  categoria: string;
  fornecedor: string;
  codigoFornecedor: string | null;
  unidade: string;
  tamanho: string | null;
  precoParcelado: number;
  precoAVista: number;
  condicaoParcelado: string;
  tabela: string;
  /** Primeiro dia do mês de vigência da tabela (YYYY-MM-DD). */
  vigencia: string;
  desatualizada: boolean;
}

